CREATE TABLE rubrics (
  id TEXT NOT NULL PRIMARY KEY,
  source_text TEXT NOT NULL CHECK (length(trim(source_text)) > 0),
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE rubric_criteria (
  rubric_id TEXT NOT NULL REFERENCES rubrics(id),
  criterion_id INTEGER NOT NULL CHECK (criterion_id >= 1),
  name TEXT NOT NULL CHECK (length(trim(name)) > 0),
  position INTEGER NOT NULL CHECK (position >= 1),
  min_score INTEGER NOT NULL,
  max_score INTEGER NOT NULL,
  PRIMARY KEY (rubric_id, criterion_id),
  UNIQUE (rubric_id, name),
  UNIQUE (rubric_id, position),
  CHECK (1 <= min_score AND min_score < max_score AND max_score <= 5),
  CHECK (criterion_id IS NULL OR typeof(criterion_id) = 'integer'),
  CHECK (position IS NULL OR typeof(position) = 'integer'),
  CHECK (min_score IS NULL OR typeof(min_score) = 'integer'),
  CHECK (max_score IS NULL OR typeof(max_score) = 'integer')
);

CREATE TABLE rubric_levels (
  rubric_id TEXT NOT NULL,
  criterion_id INTEGER NOT NULL,
  score INTEGER NOT NULL,
  description TEXT NOT NULL CHECK (length(trim(description)) > 0),
  PRIMARY KEY (rubric_id, criterion_id, score),
  FOREIGN KEY (rubric_id, criterion_id) REFERENCES rubric_criteria(rubric_id, criterion_id),
  CHECK (criterion_id IS NULL OR typeof(criterion_id) = 'integer'),
  CHECK (score IS NULL OR typeof(score) = 'integer')
);

CREATE TABLE sessions (
  id TEXT NOT NULL PRIMARY KEY,
  participant_id TEXT NOT NULL,
  condition TEXT NOT NULL CHECK (condition IN ('baseline', 'dashboard')),
  essay_set TEXT NOT NULL,
  rubric_id TEXT NOT NULL REFERENCES rubrics(id),
  use_precomputed_topics INTEGER NOT NULL DEFAULT 0 CHECK (use_precomputed_topics IN (0, 1)),
  precomputed_k INTEGER CHECK (precomputed_k IS NULL OR precomputed_k >= 2),
  precompute_grades INTEGER NOT NULL DEFAULT 1 CHECK (precompute_grades IN (0, 1)),
  grades_precomputed INTEGER NOT NULL DEFAULT 0 CHECK (grades_precomputed IN (0, 1)),
  use_cached_assessments INTEGER NOT NULL DEFAULT 0 CHECK (use_cached_assessments IN (0, 1)),
  assessment_type TEXT NOT NULL DEFAULT 'flow' CHECK (assessment_type IN ('flow', 'bullets')),
  assessment_length TEXT NOT NULL DEFAULT 'medium' CHECK (assessment_length IN ('short', 'medium', 'long')),
  processing_status TEXT NOT NULL DEFAULT 'pending' CHECK (processing_status IN
    ('pending', 'processing', 'summarising', 'topics', 'similarities', 'complete', 'error')),
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  completed_at DATETIME,
  UNIQUE (id, rubric_id),
  CHECK (use_precomputed_topics IS NULL OR typeof(use_precomputed_topics) = 'integer'),
  CHECK (precomputed_k IS NULL OR typeof(precomputed_k) = 'integer'),
  CHECK (precompute_grades IS NULL OR typeof(precompute_grades) = 'integer'),
  CHECK (grades_precomputed IS NULL OR typeof(grades_precomputed) = 'integer'),
  CHECK (use_cached_assessments IS NULL OR typeof(use_cached_assessments) = 'integer')
);

CREATE TABLE essays (
  id TEXT NOT NULL PRIMARY KEY,
  session_id TEXT NOT NULL REFERENCES sessions(id),
  dataset_essay_id TEXT NOT NULL,
  source_path TEXT NOT NULL,
  essay_prompt TEXT,
  essay_text TEXT NOT NULL,
  summary TEXT,
  word_count INTEGER CHECK (word_count IS NULL OR word_count >= 0),
  is_flagged INTEGER NOT NULL DEFAULT 0 CHECK (is_flagged IN (0, 1)),
  grading_status TEXT NOT NULL DEFAULT 'pending' CHECK (grading_status IN ('pending', 'grading', 'graded')),
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE (session_id, dataset_essay_id),
  UNIQUE (id, session_id),
  CHECK (word_count IS NULL OR typeof(word_count) = 'integer'),
  CHECK (is_flagged IS NULL OR typeof(is_flagged) = 'integer'),
  CHECK (length(trim(dataset_essay_id)) > 0)
);

CREATE TABLE topics (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  session_id TEXT NOT NULL REFERENCES sessions(id),
  topic_index INTEGER NOT NULL CHECK (topic_index >= 0),
  keywords TEXT NOT NULL,
  label TEXT,
  UNIQUE (session_id, topic_index),
  UNIQUE (id, session_id),
  CHECK (id IS NULL OR typeof(id) = 'integer'),
  CHECK (topic_index IS NULL OR typeof(topic_index) = 'integer'),
  CHECK (keywords IS NULL OR (json_valid(keywords) AND json_type(keywords) = 'array'))
);

CREATE TABLE topic_assignments (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  session_id TEXT NOT NULL,
  essay_id TEXT NOT NULL,
  topic_id INTEGER,
  source TEXT NOT NULL CHECK (source IN ('model', 'manual')),
  assigned_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CHECK (source = 'manual' OR topic_id IS NOT NULL),
  FOREIGN KEY (essay_id, session_id) REFERENCES essays(id, session_id),
  FOREIGN KEY (topic_id, session_id) REFERENCES topics(id, session_id),
  CHECK (id IS NULL OR typeof(id) = 'integer'),
  CHECK (topic_id IS NULL OR typeof(topic_id) = 'integer')
);

CREATE TABLE grades (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  session_id TEXT NOT NULL,
  essay_id TEXT NOT NULL,
  rubric_id TEXT NOT NULL,
  criterion_id INTEGER NOT NULL,
  teacher_score INTEGER CHECK (teacher_score IS NULL OR teacher_score BETWEEN 1 AND 5),
  ai_score INTEGER CHECK (ai_score IS NULL OR ai_score BETWEEN 1 AND 5),
  original_ai_score INTEGER CHECK (original_ai_score IS NULL OR original_ai_score BETWEEN 1 AND 5),
  teacher_justification TEXT,
  ai_justification TEXT,
  evidence_json TEXT CHECK (evidence_json IS NULL OR json_valid(evidence_json)),
  graded_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  UNIQUE (session_id, essay_id, criterion_id),
  FOREIGN KEY (essay_id, session_id) REFERENCES essays(id, session_id),
  FOREIGN KEY (session_id, rubric_id) REFERENCES sessions(id, rubric_id),
  FOREIGN KEY (rubric_id, criterion_id) REFERENCES rubric_criteria(rubric_id, criterion_id),
  CHECK (id IS NULL OR typeof(id) = 'integer'),
  CHECK (criterion_id IS NULL OR typeof(criterion_id) = 'integer'),
  CHECK (teacher_score IS NULL OR typeof(teacher_score) = 'integer'),
  CHECK (ai_score IS NULL OR typeof(ai_score) = 'integer'),
  CHECK (original_ai_score IS NULL OR typeof(original_ai_score) = 'integer'),
  CHECK (evidence_json IS NULL OR (json_valid(evidence_json) AND json_type(evidence_json) = 'array'))
);

CREATE TABLE benchmarks (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  session_id TEXT NOT NULL,
  rubric_id TEXT NOT NULL,
  criterion_id INTEGER NOT NULL,
  score INTEGER NOT NULL CHECK (score BETWEEN 1 AND 5),
  essay_id TEXT NOT NULL,
  teacher_justification TEXT,
  ai_justification TEXT,
  set_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  UNIQUE (session_id, criterion_id, score),
  FOREIGN KEY (essay_id, session_id) REFERENCES essays(id, session_id),
  FOREIGN KEY (session_id, rubric_id) REFERENCES sessions(id, rubric_id),
  FOREIGN KEY (rubric_id, criterion_id) REFERENCES rubric_criteria(rubric_id, criterion_id),
  CHECK (id IS NULL OR typeof(id) = 'integer'),
  CHECK (criterion_id IS NULL OR typeof(criterion_id) = 'integer'),
  CHECK (score IS NULL OR typeof(score) = 'integer')
);

CREATE TABLE teacher_highlights (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  session_id TEXT NOT NULL,
  essay_id TEXT NOT NULL,
  rubric_id TEXT NOT NULL,
  criterion_id INTEGER NOT NULL,
  start_index INTEGER NOT NULL CHECK (start_index >= 0),
  end_index INTEGER NOT NULL CHECK (end_index > start_index),
  text TEXT NOT NULL,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (essay_id, session_id) REFERENCES essays(id, session_id),
  FOREIGN KEY (session_id, rubric_id) REFERENCES sessions(id, rubric_id),
  FOREIGN KEY (rubric_id, criterion_id) REFERENCES rubric_criteria(rubric_id, criterion_id),
  CHECK (id IS NULL OR typeof(id) = 'integer'),
  CHECK (criterion_id IS NULL OR typeof(criterion_id) = 'integer'),
  CHECK (start_index IS NULL OR typeof(start_index) = 'integer'),
  CHECK (end_index IS NULL OR typeof(end_index) = 'integer')
);

CREATE TABLE essay_similarities (
  session_id TEXT NOT NULL,
  essay_id_a TEXT NOT NULL,
  essay_id_b TEXT NOT NULL,
  similarity_score REAL NOT NULL CHECK (similarity_score BETWEEN -1 AND 1),
  embedding_model TEXT,
  embedding_input_version TEXT,
  PRIMARY KEY (session_id, essay_id_a, essay_id_b),
  CHECK (essay_id_a <> essay_id_b),
  CHECK ((embedding_model IS NULL) = (embedding_input_version IS NULL)),
  FOREIGN KEY (essay_id_a, session_id) REFERENCES essays(id, session_id),
  FOREIGN KEY (essay_id_b, session_id) REFERENCES essays(id, session_id)
);

CREATE TABLE essay_summaries (
  cache_key TEXT NOT NULL PRIMARY KEY,
  content_hash TEXT NOT NULL,
  model TEXT NOT NULL,
  prompt_version INTEGER NOT NULL,
  summary TEXT NOT NULL CHECK (length(trim(summary)) > 0),
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CHECK (prompt_version IS NULL OR typeof(prompt_version) = 'integer')
);

CREATE TABLE essay_embeddings (
  cache_key TEXT NOT NULL PRIMARY KEY,
  content_hash TEXT NOT NULL,
  model TEXT NOT NULL,
  input_version TEXT NOT NULL,
  dimensions INTEGER NOT NULL CHECK (dimensions > 0),
  embedding_json TEXT NOT NULL
    CHECK (json_valid(embedding_json) AND json_array_length(embedding_json) = dimensions),
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CHECK (dimensions IS NULL OR typeof(dimensions) = 'integer'),
  CHECK (embedding_json IS NULL OR (json_valid(embedding_json) AND json_type(embedding_json) = 'array'))
);

CREATE TABLE ai_assessments (
  cache_key TEXT NOT NULL PRIMARY KEY,
  content_hash TEXT NOT NULL,
  criterion_id INTEGER NOT NULL,
  criterion_hash TEXT NOT NULL,
  model TEXT NOT NULL,
  prompt_version INTEGER NOT NULL,
  assessment_type TEXT NOT NULL,
  assessment_length TEXT NOT NULL,
  status TEXT NOT NULL CHECK (status IN ('success', 'failed')),
  score INTEGER CHECK (score IS NULL OR score BETWEEN 1 AND 5),
  justification TEXT,
  evidence_json TEXT CHECK (evidence_json IS NULL OR json_valid(evidence_json)),
  error TEXT,
  attempts INTEGER NOT NULL DEFAULT 1 CHECK (attempts >= 1),
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CHECK (status = 'failed' OR (score IS NOT NULL AND justification IS NOT NULL)),
  CHECK (status = 'success' OR error IS NOT NULL),
  CHECK (criterion_id IS NULL OR typeof(criterion_id) = 'integer'),
  CHECK (prompt_version IS NULL OR typeof(prompt_version) = 'integer'),
  CHECK (score IS NULL OR typeof(score) = 'integer'),
  CHECK (attempts IS NULL OR typeof(attempts) = 'integer'),
  CHECK (evidence_json IS NULL OR (json_valid(evidence_json) AND json_type(evidence_json) = 'array'))
);

CREATE TABLE topic_models (
  cache_key TEXT NOT NULL PRIMARY KEY,
  essay_set TEXT NOT NULL,
  input_hash TEXT NOT NULL,
  k INTEGER NOT NULL CHECK (k >= 2),
  embed_model TEXT NOT NULL,
  llm_model TEXT NOT NULL,
  method_version INTEGER NOT NULL,
  preprocessing TEXT,
  topics_json TEXT NOT NULL CHECK (json_valid(topics_json)),
  assignments_json TEXT NOT NULL CHECK (json_valid(assignments_json)),
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CHECK (k IS NULL OR typeof(k) = 'integer'),
  CHECK (method_version IS NULL OR typeof(method_version) = 'integer'),
  CHECK (topics_json IS NULL OR (json_valid(topics_json) AND json_type(topics_json) = 'array')),
  CHECK (assignments_json IS NULL OR (json_valid(assignments_json) AND json_type(assignments_json) = 'object'))
);

CREATE TABLE pipeline_runs (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  session_id TEXT NOT NULL REFERENCES sessions(id),
  pipeline_type TEXT NOT NULL CHECK (pipeline_type IN ('cohort_processing', 'grading_precompute')),
  status TEXT NOT NULL CHECK (status IN ('running', 'success', 'partial', 'failed', 'interrupted')),
  instance_id TEXT NOT NULL,
  input_hash TEXT NOT NULL,
  config_json TEXT NOT NULL CHECK (json_valid(config_json)),
  expected_items INTEGER NOT NULL CHECK (expected_items >= 0),
  processed_items INTEGER NOT NULL DEFAULT 0 CHECK (processed_items >= 0),
  failed_items INTEGER NOT NULL DEFAULT 0 CHECK (failed_items >= 0),
  started_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  finished_at DATETIME,
  error_message TEXT,
  CHECK (processed_items + failed_items <= expected_items),
  CHECK ((status = 'running') = (finished_at IS NULL)),
  CHECK (id IS NULL OR typeof(id) = 'integer'),
  CHECK (expected_items IS NULL OR typeof(expected_items) = 'integer'),
  CHECK (processed_items IS NULL OR typeof(processed_items) = 'integer'),
  CHECK (failed_items IS NULL OR typeof(failed_items) = 'integer'),
  CHECK (config_json IS NULL OR (json_valid(config_json) AND json_type(config_json) = 'object'))
);

CREATE TABLE action_logs (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  session_id TEXT NOT NULL REFERENCES sessions(id),
  participant_id TEXT NOT NULL,
  condition TEXT NOT NULL,
  essay_set TEXT NOT NULL,
  essay_id TEXT,
  action_type TEXT NOT NULL,
  action_detail TEXT,
  timestamp DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (essay_id, session_id) REFERENCES essays(id, session_id),
  CHECK (id IS NULL OR typeof(id) = 'integer')
);

CREATE VIEW essay_current_topics AS
  SELECT ta.session_id, ta.essay_id, ta.topic_id, ta.source, ta.assigned_at
  FROM topic_assignments ta
  WHERE ta.id = (SELECT MAX(id) FROM topic_assignments latest WHERE latest.essay_id = ta.essay_id);

CREATE VIEW essay_scores AS
  SELECT e.id AS essay_id,
    (SELECT AVG(g.teacher_score) FROM grades g WHERE g.session_id = e.session_id AND g.essay_id = e.id) AS overall_grade,
    (SELECT AVG(g.ai_score) FROM grades g WHERE g.session_id = e.session_id AND g.essay_id = e.id) AS avg_ai_score
  FROM essays e;

CREATE INDEX idx_topic_assignments_essay ON topic_assignments (essay_id, id);

CREATE INDEX idx_topic_assignments_session ON topic_assignments (session_id, id);

CREATE INDEX idx_highlights_session_essay ON teacher_highlights (session_id, essay_id, start_index);

CREATE INDEX idx_essay_embeddings_model ON essay_embeddings (model, input_version, dimensions);

CREATE INDEX idx_topic_models_inputs ON topic_models (essay_set, input_hash, embed_model, llm_model, method_version);

CREATE INDEX idx_pipeline_runs_latest ON pipeline_runs (session_id, pipeline_type, id);

CREATE UNIQUE INDEX idx_pipeline_runs_one_running
  ON pipeline_runs (session_id, pipeline_type) WHERE status = 'running';

CREATE INDEX idx_action_logs_session_time ON action_logs (session_id, timestamp);

CREATE INDEX idx_action_logs_session_type ON action_logs (session_id, action_type, timestamp);

CREATE TRIGGER rubric_criteria_preserve_ranges BEFORE UPDATE OF min_score, max_score ON rubric_criteria
  WHEN EXISTS (SELECT 1 FROM rubric_levels WHERE rubric_id = OLD.rubric_id AND criterion_id = OLD.criterion_id
    AND score NOT BETWEEN NEW.min_score AND NEW.max_score)
    OR EXISTS (SELECT 1 FROM grades WHERE rubric_id = OLD.rubric_id AND criterion_id = OLD.criterion_id
      AND (teacher_score NOT BETWEEN NEW.min_score AND NEW.max_score
        OR ai_score NOT BETWEEN NEW.min_score AND NEW.max_score
        OR original_ai_score NOT BETWEEN NEW.min_score AND NEW.max_score))
    OR EXISTS (SELECT 1 FROM benchmarks WHERE rubric_id = OLD.rubric_id AND criterion_id = OLD.criterion_id
      AND score NOT BETWEEN NEW.min_score AND NEW.max_score)
  BEGIN SELECT RAISE(ABORT, 'criterion range excludes existing scores'); END;

CREATE TRIGGER rubric_levels_score_range_insert BEFORE INSERT ON rubric_levels
  WHEN EXISTS (SELECT 1 FROM rubric_criteria rc
    WHERE rc.rubric_id = NEW.rubric_id AND rc.criterion_id = NEW.criterion_id
      AND ((NEW.score IS NOT NULL AND
  NEW.score NOT BETWEEN rc.min_score AND rc.max_score)))
  BEGIN SELECT RAISE(ABORT, 'score outside criterion range'); END;

CREATE TRIGGER rubric_levels_score_range_update BEFORE UPDATE ON rubric_levels
  WHEN EXISTS (SELECT 1 FROM rubric_criteria rc
    WHERE rc.rubric_id = NEW.rubric_id AND rc.criterion_id = NEW.criterion_id
      AND ((NEW.score IS NOT NULL AND
  NEW.score NOT BETWEEN rc.min_score AND rc.max_score)))
  BEGIN SELECT RAISE(ABORT, 'score outside criterion range'); END;

CREATE TRIGGER grades_original_score_first_ai AFTER UPDATE OF ai_score ON grades
  WHEN NEW.original_ai_score IS NULL AND NEW.ai_score IS NOT NULL
  BEGIN UPDATE grades SET original_ai_score = NEW.ai_score WHERE id = NEW.id; END;

CREATE TRIGGER grades_original_score_insert AFTER INSERT ON grades
  WHEN NEW.original_ai_score IS NULL AND NEW.ai_score IS NOT NULL
  BEGIN UPDATE grades SET original_ai_score = NEW.ai_score WHERE id = NEW.id; END;

CREATE TRIGGER grades_original_score_preserve BEFORE UPDATE OF original_ai_score ON grades
  WHEN OLD.original_ai_score IS NOT NULL AND NEW.original_ai_score IS NOT OLD.original_ai_score
  BEGIN SELECT RAISE(ABORT, 'original AI score cannot change'); END;

CREATE TRIGGER grades_original_score_valid_insert BEFORE INSERT ON grades
  WHEN NEW.original_ai_score IS NOT NULL AND NEW.original_ai_score IS NOT NEW.ai_score
  BEGIN SELECT RAISE(ABORT, 'original AI score must be the first AI score'); END;

CREATE TRIGGER grades_original_score_valid_update BEFORE UPDATE OF original_ai_score ON grades
  WHEN OLD.original_ai_score IS NULL AND NEW.original_ai_score IS NOT NULL
    AND NEW.original_ai_score IS NOT NEW.ai_score
  BEGIN SELECT RAISE(ABORT, 'original AI score must be the first AI score'); END;

CREATE TRIGGER grades_score_range_insert BEFORE INSERT ON grades
  WHEN EXISTS (SELECT 1 FROM rubric_criteria rc
    WHERE rc.rubric_id = NEW.rubric_id AND rc.criterion_id = NEW.criterion_id
      AND ((NEW.teacher_score IS NOT NULL AND
  NEW.teacher_score NOT BETWEEN rc.min_score AND rc.max_score) OR (NEW.ai_score IS NOT NULL AND
  NEW.ai_score NOT BETWEEN rc.min_score AND rc.max_score) OR (NEW.original_ai_score IS NOT NULL AND
  NEW.original_ai_score NOT BETWEEN rc.min_score AND rc.max_score)))
  BEGIN SELECT RAISE(ABORT, 'score outside criterion range'); END;

CREATE TRIGGER grades_score_range_update BEFORE UPDATE ON grades
  WHEN EXISTS (SELECT 1 FROM rubric_criteria rc
    WHERE rc.rubric_id = NEW.rubric_id AND rc.criterion_id = NEW.criterion_id
      AND ((NEW.teacher_score IS NOT NULL AND
  NEW.teacher_score NOT BETWEEN rc.min_score AND rc.max_score) OR (NEW.ai_score IS NOT NULL AND
  NEW.ai_score NOT BETWEEN rc.min_score AND rc.max_score) OR (NEW.original_ai_score IS NOT NULL AND
  NEW.original_ai_score NOT BETWEEN rc.min_score AND rc.max_score)))
  BEGIN SELECT RAISE(ABORT, 'score outside criterion range'); END;

CREATE TRIGGER benchmarks_score_range_insert BEFORE INSERT ON benchmarks
  WHEN EXISTS (SELECT 1 FROM rubric_criteria rc
    WHERE rc.rubric_id = NEW.rubric_id AND rc.criterion_id = NEW.criterion_id
      AND ((NEW.score IS NOT NULL AND
  NEW.score NOT BETWEEN rc.min_score AND rc.max_score)))
